/**
 * codex-search.json's keyword postings find a document by any term of its text, wherever in the document it sits.
 *
 * scripts/auto-index.js keeps each document's first 5,000 characters in the index's content field, and the postings were
 * built from that field: a term past that point never reached its document, the cut left a fragment of the word it fell
 * in, and an edit near a document's top pushed later terms out of search. Pull request 13's edits to docs/DEVELOPMENT.md
 * and docs/RECATALOG_GUIDE.md moved the first's SQL cache section and the second's "auto-generated" and "Reviewing" lines
 * past the cut, and the index of pull request 14 no longer found the guides by architecture, sqlite3, generated or
 * reviewing.
 *
 * The cases index their documents with the indexer, write codex-index.json as it does, and run the search build on it
 * (scripts/search-index.mjs) with a stand-in for the embedding model, which the build would otherwise download.
 *
 * Run: npx vitest run tests/search-index.test.js
 */

import { describe, it, expect, afterEach, vi } from 'vitest'
import { buildSearchIndex, tokenize } from '../scripts/search-index.mjs'

const fs = require('fs')
const os = require('os')
const path = require('path')
const { CodexIndexer } = require('../scripts/auto-index.js')

const REPO = path.join(__dirname, '..')
const createEmbedder = async () => async () => ({ data: new Float32Array([1, 0, 0]) })

const scratch = []
afterEach(() => {
  while (scratch.length > 0) fs.rmSync(scratch.pop(), { recursive: true, force: true })
})

// A scratch directory holding the files given (relative path -> text), removed after the case.
const scratchDir = (files) => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'codex-search-'))
  scratch.push(dir)
  for (const [relativePath, text] of Object.entries(files)) {
    fs.mkdirSync(path.dirname(path.join(dir, relativePath)), { recursive: true })
    fs.writeFileSync(path.join(dir, relativePath), text)
  }
  return dir
}

const readSearch = (root) => JSON.parse(fs.readFileSync(path.join(root, 'codex-search.json'), 'utf8'))

// Indexes the files under root as scripts/auto-index.js does, writes codex-index.json, and builds codex-search.json.
const indexAndSearch = async (root, relativePaths) => {
  const indexer = new CodexIndexer()
  const entries = relativePaths.map((relativePath) => indexer.processFile(path.join(root, relativePath), root))
  expect(indexer.stats.errors).toEqual([])
  fs.writeFileSync(path.join(root, 'codex-index.json'), JSON.stringify(entries, null, 2))
  await buildSearchIndex({ root, createEmbedder })
  return { entries, search: readSearch(root) }
}

// The documents a search for the term reaches: those its postings name. An own key only, so a term such as
// "constructor" never reads the object's prototype.
const found = (search, term) =>
  Object.hasOwn(search.vocabulary, term) ? search.vocabulary[term].map(([docId]) => search.docs[docId].path) : []

describe('codex-search.json: a search finds a document by any term of its text', () => {
  it('finds docs/DEVELOPMENT.md and docs/RECATALOG_GUIDE.md by the terms the index of pull request 14 lost', async () => {
    const lost = {
      'docs/DEVELOPMENT.md': ['architecture', 'sqlite3', 'storage', 'adapter', 'incremental'],
      'docs/RECATALOG_GUIDE.md': ['generated', 'autogenerated', 'reviewing', 'warnings', 'suggestions'],
    }
    const guides = Object.keys(lost)
    const root = scratchDir(Object.fromEntries(guides.map((guide) => [guide, fs.readFileSync(path.join(REPO, guide), 'utf8')])))
    const { search } = await indexAndSearch(root, guides)

    for (const [guide, terms] of Object.entries(lost)) {
      const words = new Set(tokenize(fs.readFileSync(path.join(REPO, guide), 'utf8')))
      for (const term of terms) {
        expect(words.has(term), `${guide} no longer holds "${term}"; pin a term it holds`).toBe(true)
        expect(found(search, term), `a search for "${term}"`).toContain(guide)
      }
    }
  })

  it('reads a document past the index excerpt, keeps the word the excerpt cuts whole, and counts every term', async () => {
    // "architecture" starts 4 characters before the excerpt's 5,000-character cut; "zeppelin" sits past character 9,000.
    const filler = (length) => `${'Lorem ipsum dolor sit amet. '.repeat(Math.ceil(length / 28)).slice(0, length - 1)}\n`
    const body = `${filler(4996)}architecture\n${filler(4000)}zeppelin\n`
    const root = scratchDir({
      'docs/long-guide.md': `---\ntitle: Long guide\nsummary: A guide longer than the index excerpt.\n---\n${body}`,
    })
    const { entries, search } = await indexAndSearch(root, ['docs/long-guide.md'])

    expect(entries[0].content).not.toContain('architecture')
    expect(entries[0].content).not.toContain('zeppelin')
    expect(found(search, 'architecture')).toEqual(['docs/long-guide.md'])
    expect(found(search, 'zeppelin')).toEqual(['docs/long-guide.md'])
    expect(found(search, 'arch')).toEqual([])
    // BM25 divides by a document's length, which is the number of terms its postings count.
    const counted = Object.values(search.vocabulary)
      .flat()
      .reduce((sum, [docId, termFrequency]) => sum + (docId === 0 ? termFrequency : 0), 0)
    expect(search.docs[0].docLength).toBe(counted)
  })

  it('uses the index excerpt for a listed document whose file is missing or outside the root, through a link too, and says which', async () => {
    const parent = scratchDir({ 'outside.md': 'nebula\n' })
    const root = path.join(parent, 'root')
    fs.mkdirSync(path.join(root, 'docs'), { recursive: true })
    // A link under the root whose target lies outside it: the indexer lists it by the link's name.
    fs.symlinkSync(path.join(parent, 'outside.md'), path.join(root, 'docs', 'leak.md'))
    fs.writeFileSync(
      path.join(root, 'codex-index.json'),
      JSON.stringify([
        { path: 'docs/gone.md', name: 'gone.md', metadata: { title: 'Gone' }, content: 'quasar' },
        { path: '../outside.md', name: 'outside.md', metadata: { title: 'Outside' }, content: 'pulsar' },
        { path: 'docs/leak.md', name: 'leak.md', metadata: { title: 'Leak' }, content: 'comet' },
      ]),
    )
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
    try {
      await buildSearchIndex({ root, createEmbedder })
      const search = readSearch(root)
      expect(found(search, 'quasar')).toEqual(['docs/gone.md'])
      expect(found(search, 'pulsar')).toEqual(['../outside.md'])
      expect(found(search, 'comet')).toEqual(['docs/leak.md'])
      expect(found(search, 'nebula')).toEqual([])
      const lines = warn.mock.calls.map((call) => call.join(' '))
      expect(lines).toHaveLength(3)
      expect(lines[0]).toContain('docs/gone.md')
      expect(lines[1]).toContain('../outside.md')
      expect(lines[2]).toContain('docs/leak.md')
    } finally {
      warn.mockRestore()
    }
  })
})
